package dev.jackteng.figura;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import jakarta.servlet.http.Cookie;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.autoconfigure.web.servlet.MockMvcPrint;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.ActiveProfiles;
import org.springframework.test.web.servlet.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;

/** Complete security chain + real isolated MySQL/Redis, never a production database. */
@SpringBootTest @AutoConfigureMockMvc(print=MockMvcPrint.NONE) @ActiveProfiles("demo")
@EnabledIfEnvironmentVariable(named="SHOP_MYSQL_INTEGRATION",matches="true")
class PreorderBatchIntegrationTest {
    @Autowired MockMvc mvc;
    @Autowired ObjectMapper json;
    @org.springframework.boot.test.mock.mockito.SpyBean JdbcTemplate jdbc;
    @Autowired dev.jackteng.figura.service.PreorderBatchService batches;
    @Autowired dev.jackteng.figura.service.CatalogService catalog;
    @Autowired StringRedisTemplate redis;
    private final Set<String> ids=ConcurrentHashMap.newKeySet();
    private final Set<String> sessionKeys=ConcurrentHashMap.newKeySet();
    record Client(String csrf,List<Cookie> cookies) {}
    private Cookie cookie(MvcResult r,String name){var header=r.getResponse().getHeaders("Set-Cookie").stream().filter(h->h.startsWith(name+"=")).findFirst().orElseThrow();return new Cookie(name,header.split(";",2)[0].substring(name.length()+1));}
    private JsonNode data(MvcResult r) throws Exception{return json.readTree(r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8)).path("data");}
    private MvcResult call(Client c,String method,String path,Object body) throws Exception{
        var b=request(org.springframework.http.HttpMethod.valueOf(method),"/figura/api"+path).contextPath("/figura").servletPath("/api"+path.split("\\?",2)[0]);
        if(c!=null){b.cookie(c.cookies().toArray(Cookie[]::new));if(!method.equals("GET"))b.header("X-XSRF-TOKEN",c.csrf());}
        if(body!=null)b.contentType("application/json").content(json.writeValueAsBytes(body));
        return mvc.perform(b).andReturn();
    }
    private Client guest() throws Exception{var r=call(null,"GET","/auth/csrf",null);return new Client(data(r).path("token").asText(),List.of(cookie(r,"XSRF-TOKEN")));}
    private Client staff(boolean admin) throws Exception{
        var c=guest();String device=UUID.randomUUID().toString(),name=admin?"shop_admin":"shop_staff";
        var r=mvc.perform(post("/figura/api/admin/login").contextPath("/figura").servletPath("/api/admin/login").cookie(c.cookies().toArray(Cookie[]::new)).header("X-XSRF-TOKEN",c.csrf()).param("username",name).param("password",System.getenv(admin?"DEMO_ADMIN_PASSWORD":"DEMO_STAFF_PASSWORD")).param("deviceId",device)).andReturn();assertEquals(200,r.getResponse().getStatus());
        sessionKeys.add("shop:session:"+data(r).path("id").asInt()+":"+device);
        return new Client(c.csrf(),List.of(c.cookies().get(0),cookie(r,"accessToken"),cookie(r,"refreshToken")));
    }
    private Map<String,Object> sku(String code,boolean enabled){return new HashMap<>(Map.of("code",code,"label","初回限定款","priceTwd",1280,"enabled",enabled));}
    private Map<String,Object> product(List<Map<String,Object>> skus){return new HashMap<>(Map.of("title","integration collection "+UUID.randomUUID(),"brand","Figura","category","公仔","description","<script>資料是文字</script>","expectedVersion",0,"skus",skus));}
    private String code(){return "TEST-"+UUID.randomUUID();}
    private JsonNode create(Client c,Map<String,Object> input) throws Exception{var r=call(c,"POST","/admin/products",input);assertEquals(201,r.getResponse().getStatus(),r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));var p=data(r);ids.add(p.path("id").asText());return p;}
    private Map<String,Object> write(JsonNode p){return new HashMap<>(Map.of("title",p.path("title").asText(),"brand",p.path("brand").asText(),"category",p.path("category").asText(),"description",p.path("description").asText(),"expectedVersion",p.path("version").asInt(),"skus",json.convertValue(p.path("skus"),List.class)));}
    private MvcResult publish(Client c,JsonNode p,boolean yes) throws Exception{return call(c,"PATCH","/admin/products/"+p.path("id").asText()+"/publication",Map.of("expectedVersion",p.path("version").asInt(),"published",yes));}

    private final Set<String> batchIds=ConcurrentHashMap.newKeySet();
    @AfterEach void cleanup(){for(String id:ids)jdbc.update("UPDATE catalog_product SET status='ARCHIVED' WHERE id=?",id);if(!sessionKeys.isEmpty())redis.delete(sessionKeys);}
    private JsonNode product(Client a,boolean published)throws Exception{var p=create(a,product(List.of(sku(code(),true))));return published?data(publish(a,p,true)):p;}
    private Map<String,Object> batchWrite(JsonNode p){var now=java.time.OffsetDateTime.now(java.time.ZoneOffset.ofHours(8)).withNano(0);return new HashMap<>(Map.ofEntries(Map.entry("productId",p.path("id").asText()),Map.entry("skuId",p.path("skus").get(0).path("id").asText()),Map.entry("name","Batch "+UUID.randomUUID()),Map.entry("description","<img src=x onerror=alert(1)>"),Map.entry("priceTwd",1800),Map.entry("capacity",15),Map.entry("deadlineAt",now.plusDays(1).toString()),Map.entry("arrivalFrom",now.plusDays(30).toLocalDate().toString()),Map.entry("arrivalTo",now.plusDays(40).toLocalDate().toString()),Map.entry("expectedVersion",0),Map.entry("requestId",UUID.randomUUID().toString()),Map.entry("note","synthetic fixture")));}
    private JsonNode batch(Client a,JsonNode p)throws Exception{var r=call(a,"POST","/admin/preorders",batchWrite(p));assertEquals(201,r.getResponse().getStatus(),r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));var b=data(r).path("current");batchIds.add(b.path("id").asText());return b;}
    private String path(JsonNode b){return "/admin/preorders/"+b.path("id").asText();}
    private String pub(JsonNode b){return "/catalog/preorders/"+b.path("id").asText();}
    private Map<String,Object> command(JsonNode b){return new HashMap<>(Map.of("expectedVersion",b.path("version").asInt(),"requestId",UUID.randomUUID().toString(),"note","synthetic lifecycle"));}
    private JsonNode action(Client a,JsonNode b,String action)throws Exception{var r=call(a,"POST",path(b)+"/"+action,command(b));assertEquals(201,r.getResponse().getStatus(),r.getResponse().getContentAsString(java.nio.charset.StandardCharsets.UTF_8));return data(r).path("current");}
    private Map<String,Object> edit(JsonNode p,JsonNode b){var w=batchWrite(p);for(String field:List.of("name","description","deadlineAt","arrivalFrom","arrivalTo"))w.put(field,b.path(field).asText());w.put("priceTwd",b.path("priceTwd").asInt());w.put("capacity",b.path("capacity").asInt());w.put("expectedVersion",b.path("version").asInt());return w;}
    private List<Integer> race(Callable<Integer> one,Callable<Integer> two)throws Exception{var pool=Executors.newFixedThreadPool(2);var start=new CountDownLatch(1);try{var f=pool.submit(()->{start.await();return one.call();});var g=pool.submit(()->{start.await();return two.call();});start.countDown();return List.of(f.get(20,TimeUnit.SECONDS),g.get(20,TimeUnit.SECONDS));}finally{pool.shutdownNow();}}
    @Test void lifecycleFreezesTermsAndDoesNotTouchPhysicalInventory()throws Exception{var a=staff(true);var p=product(a,false);var b=batch(a,p);var sku=p.path("skus").get(0).path("id").asText();var stock=jdbc.queryForMap("SELECT * FROM sku_inventory WHERE sku_id=?",sku);assertEquals(404,call(null,"GET",pub(b),null).getResponse().getStatus());assertEquals(409,call(a,"POST",path(b)+"/open",command(b)).getResponse().getStatus());p=data(publish(a,p,true));var body=command(b);var opened=call(a,"POST",path(b)+"/open",body);assertEquals(201,opened.getResponse().getStatus());b=data(opened).path("current");assertEquals("OPEN",b.path("status").asText());var v=data(call(null,"GET",pub(b),null));assertFalse(v.has("version"));assertFalse(v.has("skuId"));assertFalse(v.has("heldQuantity"));assertTrue(v.path("orderingEnabled").asBoolean());assertEquals(15,v.path("availableQuota").asInt());assertEquals(409,call(a,"PUT",path(b),edit(p,b)).getResponse().getStatus());b=action(a,b,"close");assertEquals("CLOSED",data(call(null,"GET",pub(b),null)).path("status").asText());assertEquals(409,call(a,"POST",path(b)+"/open",command(b)).getResponse().getStatus());var retry=call(a,"POST",path(b)+"/open",body);assertEquals(200,retry.getResponse().getStatus());assertEquals("CLOSED",data(retry).path("current").path("status").asText());assertEquals(stock,jdbc.queryForMap("SELECT * FROM sku_inventory WHERE sku_id=?",sku));assertEquals(3,data(call(a,"GET",path(b),null)).path("events").size());}
    @Test void createReplayUsesNormalizedContentAndSafeAudit()throws Exception{var a=staff(true);var p=product(a,true);var w=batchWrite(p);w.put("name","  Normalized "+UUID.randomUUID()+"  ");var first=call(a,"POST","/admin/preorders",w);assertEquals(201,first.getResponse().getStatus());var b=data(first).path("current");assertEquals(w.get("name").toString().trim(),b.path("name").asText());w.put("name",w.get("name").toString().trim());w.put("deadlineAt",java.time.OffsetDateTime.parse(w.get("deadlineAt").toString()).withOffsetSameInstant(java.time.ZoneOffset.UTC).toString());assertEquals(200,call(a,"POST","/admin/preorders",w).getResponse().getStatus());w.put("capacity",16);assertEquals(409,call(a,"POST","/admin/preorders",w).getResponse().getStatus());var e=data(call(a,"GET",path(b),null)).path("events").get(0);assertFalse(e.has("fingerprint"));assertTrue(e.path("createdAt").asText().endsWith("+08:00"));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM preorder_batch_event WHERE request_id=?",Integer.class,w.get("requestId")));}
    @Test void validationRejectsInjectedFieldsInvalidDatesAndNonIntegerAmounts()throws Exception{var a=staff(true);var p=product(a,true);var w=batchWrite(p);for(String key:List.of("actorId","status","heldQuantity","paidQuantity","version","ownerId")){var bad=new HashMap<>(w);bad.put(key,"spoof");assertEquals(400,call(a,"POST","/admin/preorders",bad).getResponse().getStatus());}for(var pair:List.of(Map.entry("capacity",0),Map.entry("priceTwd",1800.5),Map.entry("capacity",100001))){var bad=new HashMap<>(w);bad.put(pair.getKey(),pair.getValue());assertEquals(400,call(a,"POST","/admin/preorders",bad).getResponse().getStatus());}var bad=new HashMap<>(w);bad.put("arrivalFrom","2000-01-01");assertEquals(400,call(a,"POST","/admin/preorders",bad).getResponse().getStatus());bad=new HashMap<>(w);bad.put("deadlineAt",java.time.OffsetDateTime.now().minusDays(1).withNano(0).toString());assertEquals(409,call(a,"POST","/admin/preorders",bad).getResponse().getStatus());bad=new HashMap<>(w);bad.put("deadlineAt",java.time.OffsetDateTime.now().plusDays(1).withNano(1).toString());assertEquals(400,call(a,"POST","/admin/preorders",bad).getResponse().getStatus());assertEquals(400,call(a,"GET","/admin/preorders?pageSize=51",null).getResponse().getStatus());assertEquals(400,call(null,"GET","/catalog/preorders?page=0",null).getResponse().getStatus());assertEquals(400,call(null,"GET","/catalog/preorders/bad-id",null).getResponse().getStatus());}
    @Test void skuOwnershipAndImmutableAssociationEnforced()throws Exception{var a=staff(true);var p=product(a,true);var q=product(a,true);var w=batchWrite(p);w.put("skuId",q.path("skus").get(0).path("id").asText());assertEquals(409,call(a,"POST","/admin/preorders",w).getResponse().getStatus());var b=batch(a,p);w=edit(q,b);assertEquals(409,call(a,"PUT",path(b),w).getResponse().getStatus());assertEquals(p.path("id"),data(call(a,"GET",path(b),null)).path("batch").path("productId"));}
    @Test void staleAndCrossTargetReplayCannotOverwrite()throws Exception{var a=staff(true);var p=product(a,true);var b=batch(a,p);var other=batch(a,p);var w=edit(p,b);w.put("capacity",16);assertEquals(201,call(a,"PUT",path(b),w).getResponse().getStatus());assertEquals(200,call(a,"PUT",path(b),w).getResponse().getStatus());assertEquals(409,call(a,"PUT",path(other),w).getResponse().getStatus());w.put("requestId",UUID.randomUUID().toString());assertEquals(409,call(a,"PUT",path(b),w).getResponse().getStatus());assertEquals(16,data(call(a,"GET",path(b),null)).path("batch").path("capacity").asInt());}
    @Test void publicReadHidesUnpublishedOrDisabledSkuAndRetainsFrozenLabels()throws Exception{var a=staff(true);var p=product(a,true);var b=action(a,batch(a,p),"open");var original=data(call(null,"GET",pub(b),null));p=data(publish(a,p,false));assertEquals(404,call(null,"GET",pub(b),null).getResponse().getStatus());var w=write(p);w.put("title","Changed product title");p=data(call(a,"PUT","/admin/products/"+p.path("id").asText(),w));p=data(publish(a,p,true));assertEquals(original,data(call(null,"GET",pub(b),null)));p=data(publish(a,p,false));w=write(p);((Map)((List)w.get("skus")).get(0)).put("enabled",false);assertEquals(200,call(a,"PUT","/admin/products/"+p.path("id").asText(),w).getResponse().getStatus());assertEquals(404,call(null,"GET",pub(b),null).getResponse().getStatus());}
    @Test void publicDeadlineExpiresWithoutMutatingAuditAndReplayStillWorks()throws Exception{var a=staff(true);var p=product(a,true);var b=batch(a,p);var command=command(b);b=data(call(a,"POST",path(b)+"/open",command)).path("current");jdbc.update("UPDATE preorder_batch SET deadline_at=DATE_SUB(CURRENT_TIMESTAMP(6),INTERVAL 1 SECOND) WHERE id=?",b.path("id").asText());assertEquals("EXPIRED",data(call(null,"GET",pub(b),null)).path("status").asText());assertEquals("OPEN",data(call(a,"GET",path(b),null)).path("batch").path("status").asText());assertEquals(200,call(a,"POST",path(b)+"/open",command).getResponse().getStatus());assertEquals(2,data(call(a,"GET",path(b),null)).path("events").size());}
    @Test void readonlyStaffRealmCsrfAndNoAuditDeletion()throws Exception{var a=staff(true);var e=staff(false);var g=guest();var p=product(a,true);var b=batch(a,p);assertEquals(200,call(e,"GET","/admin/preorders",null).getResponse().getStatus());assertEquals(200,call(e,"GET",path(b),null).getResponse().getStatus());assertEquals(403,call(e,"POST","/admin/preorders",batchWrite(p)).getResponse().getStatus());assertEquals(403,call(e,"POST",path(b)+"/open",command(b)).getResponse().getStatus());assertEquals(401,call(g,"GET","/admin/preorders",null).getResponse().getStatus());assertEquals(403,call(new Client("wrong",a.cookies()),"POST",path(b)+"/close",command(b)).getResponse().getStatus());assertEquals(403,call(a,"DELETE",path(b),null).getResponse().getStatus());assertEquals(401,call(g,"POST","/catalog/preorders",batchWrite(p)).getResponse().getStatus());}
    @Test void auditFailureRollsBackBothCreateAndLifecycle()throws Exception{var a=staff(true);var p=product(a,true);var b=batch(a,p);var w=batchWrite(p);var cmd=command(b);org.mockito.Mockito.doThrow(new org.springframework.dao.DataAccessResourceFailureException("synthetic audit failure")).when(jdbc).update(org.mockito.ArgumentMatchers.startsWith("INSERT INTO preorder_batch_event"),org.mockito.ArgumentMatchers.any(Object[].class));try{assertEquals(500,call(a,"POST","/admin/preorders",w).getResponse().getStatus());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM preorder_batch WHERE name=?",Integer.class,w.get("name")));assertEquals(500,call(a,"POST",path(b)+"/open",cmd).getResponse().getStatus());var unchanged=data(call(a,"GET",path(b),null)).path("batch");assertEquals("DRAFT",unchanged.path("status").asText());assertEquals(0,unchanged.path("version").asInt());assertEquals(0,jdbc.queryForObject("SELECT COUNT(*) FROM preorder_batch_event WHERE request_id=?",Integer.class,cmd.get("requestId")));}finally{org.mockito.Mockito.reset(jdbc);}assertEquals(201,call(a,"POST",path(b)+"/open",cmd).getResponse().getStatus());}
    @Test void concurrentReplayOnlyCreatesOneBatch()throws Exception{var a=staff(true);var p=product(a,true);var w=batchWrite(p);assertEquals(Set.of(201,200),new HashSet<>(race(()->call(a,"POST","/admin/preorders",w).getResponse().getStatus(),()->call(a,"POST","/admin/preorders",w).getResponse().getStatus())));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM preorder_batch WHERE name=?",Integer.class,w.get("name")));}
    @Test void competingEditAndOpenAndCrossActorUuidAreSerialized()throws Exception{var a=staff(true);jdbc.update("INSERT INTO role_permission VALUES(2,242),(2,243),(2,244)");try{var e=staff(false);var p=product(a,true);var b=batch(a,p);var w=edit(p,b);w.put("capacity",22);var cmd=command(b);assertEquals(Set.of(201,409),new HashSet<>(race(()->call(a,"PUT",path(b),w).getResponse().getStatus(),()->call(e,"POST",path(b)+"/open",cmd).getResponse().getStatus())));var input=batchWrite(p);assertEquals(Set.of(201,409),new HashSet<>(race(()->call(a,"POST","/admin/preorders",input).getResponse().getStatus(),()->call(e,"POST","/admin/preorders",input).getResponse().getStatus())));assertEquals(1,jdbc.queryForObject("SELECT COUNT(*) FROM preorder_batch_event WHERE request_id=?",Integer.class,input.get("requestId")));}finally{jdbc.update("DELETE FROM role_permission WHERE role_id=2 AND permission_id IN(242,243,244)");}}
    @Test void directServiceChecksLiveGrantsAndDraftCloseStaysPrivate()throws Exception{var a=staff(true);var p=product(a,true);var b=action(a,batch(a,p),"close");assertEquals(404,call(null,"GET",pub(b),null).getResponse().getStatus());assertEquals(409,call(a,"POST",path(b)+"/open",command(b)).getResponse().getStatus());jdbc.update("DELETE FROM role_permission WHERE role_id=1 AND permission_id=244");try{var actor=new dev.jackteng.figura.pojo.CustomUserDetails("spoof",jdbc.queryForObject("SELECT id FROM user WHERE username='shop_admin'",Integer.class),List.of());assertThrows(org.springframework.web.server.ResponseStatusException.class,()->batches.command(b.path("id").asText(),"OPEN",new dev.jackteng.figura.dto.PreorderPayloads.Command(b.path("version").asInt(),UUID.randomUUID().toString(),"test"),actor));}finally{jdbc.update("INSERT INTO role_permission VALUES(1,244)");}}
}
